27	func TestParseHeartbeatLine(t *testing.T) {
28		tests := []struct {
29			name    string
30			raw     string
31			wantID  string
32			wantErr bool
33		}{
34			{name: "ready with tags", raw: "dev-1|ready|1.2.3|a,b", wantID: "dev-1"},
35			{name: "lowercase status", raw: "dev-2|degraded|1.0", wantID: "dev-2"},
36			{name: "too few fields", raw: "dev-3|ready", wantErr: true},
37			{name: "empty id", raw: " |ready|1.0", wantErr: true},
38			{name: "unknown status", raw: "dev-4|SLEEPY|1.0", wantErr: true},
39		}
40		for _, tt := range tests {
41			t.Run(tt.name, func(t *testing.T) {
42				id, _, _, _, err := ParseHeartbeatLine(tt.raw)
43				if tt.wantErr { //nolint:nestif // TODO
44					if err == nil {
45						t.Fatalf("ParseHeartbeatLine(%q) expected an error", tt.raw)
46					}
47				} else {
48					if err != nil {
49						t.Fatalf("ParseHeartbeatLine(%q) unexpected error: %v", tt.raw, err)
50					}
51					if id != tt.wantID {
52						t.Errorf("id = %q, want %q", id, tt.wantID)
53					}
54				}
55			})
56		}
57	}
