59	func TestParseHeartbeatLineTags(t *testing.T) {
60		_, status, version, tags, err := ParseHeartbeatLine("dev-1|ready|1.2.3|a, b ,a,region:eu,region:zz")
61		if err != nil {
62			t.Fatalf("unexpected error: %v", err)
63		}
64		if status != models.StatusReady || version != "1.2.3" {
65			t.Errorf("status, version = %q, %q", status, version)
66		}
67		if want := []string{"a", "b", "region:eu"}; !reflect.DeepEqual(tags, want) {
68			t.Errorf("tags = %v, want %v", tags, want)
69		}
70	}
