72	func TestCacheExpiresEntries(t *testing.T) {
73		c := NewCache(50 * time.Millisecond)
74		c.Put(models.Device{ID: "d1", Tenant: "acme", Status: "READY"})
75		if _, ok := c.Get("acme/d1"); !ok {
76			t.Fatal("expected a fresh entry to be cached")
77		}
78		time.Sleep(100 * time.Millisecond)
79		if _, ok := c.Get("acme/d1"); ok {
80			t.Fatal("expected the entry to expire")
81		}
82		if c.Len() != 0 {
83			t.Errorf("Len() = %d, want 0", c.Len())
84		}
