87	func TestNotifierSend(t *testing.T) {
88		var got webhookPayload
89		var contentType string
90		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
91			contentType = r.Header.Get("Content-Type")
92			body, err := io.ReadAll(r.Body)
93			if err != nil {
94				t.Errorf("read body: %v", err)
95			}
96			if err := json.Unmarshal(body, &got); err != nil {
97				t.Errorf("decode body: %v", err)
98			}
99			w.WriteHeader(http.StatusAccepted)
100		}))
101		defer srv.Close()
102	
103		if err := NewNotifier(srv.URL).Send("ops", "device d1 is down"); err != nil {
104			t.Fatalf("Send: %v", err)
105		}
