func TestDeviceServiceGetCaches(t *testing.T) {
	ctx := context.Background()
	repo := repository.NewMemStore()
	if err := repo.Save(ctx, models.Device{ID: "d1", Tenant: "acme", Status: "READY"}); err != nil {
