14	// Notifier is a notifier.
15	type Notifier struct {
16		webhookURL string
17		client     *http.Client
18	}
19	
20	// NewNotifier creates a new Notifier.
21	func NewNotifier(webhookURL string) *Notifier {
22		return &Notifier{
23			webhookURL: webhookURL,
24			client:     &http.Client{Timeout: 5 * time.Second},
25		}
26	}
27	
28	type webhookPayload struct {
29		Channel string `json:"channel"`
30		Message string `json:"message"`
31		SentAt  string `json:"sent_at"`
32	}
33	
34	// Send sends a message on a channel. A Notifier without a webhook drops the
35	// message.
36	func (n *Notifier) Send(channel, msg string) error {
37		if n == nil || n.webhookURL == "" {
38			return nil
39		}
40		payload := webhookPayload{
41			Channel: channel,
42			Message: msg,
43			SentAt:  time.Now().UTC().Format(time.RFC3339),
44		}
45		body, err := json.Marshal(payload)
46		if err != nil {
47			return err //nolint:wrapcheck // TODO
48		}
49		contentType := "application/json" //nolint:goconst // TODO
50		resp, err := n.client.Post(n.webhookURL, contentType, bytes.NewReader(body))
51		if err != nil {
52			return err //nolint:wrapcheck // TODO
53		}
54		resp.Body.Close() //nolint:errcheck // TODO
55		if resp.StatusCode >= http.StatusMultipleChoices {
56			return fmt.Errorf("webhook %s: status %d", n.webhookURL, resp.StatusCode)
57		}
58		return nil
59	}
