63		//nolint:goconst // TODO
64		switch a.Channel {
65		case "email":
66			return sendMail(a)
67		case "slack":
68			return postSlack(a)
69		case "pagerduty":
70			return pagePagerDuty(a)
71		default:
72			return fmt.Errorf("unknown channel %q", a.Channel)
73		}
74	}
