76	func sendMail(a models.Alert) error {
77		gateway := os.Getenv("MAIL_GATEWAY")
78		if gateway == "" {
79			return nil
80		}
81		return postJSON(gateway, map[string]string{
82			"to":      a.Recipient,
83			"subject": a.Summary,
84		})
85	}
