87	func postSlack(a models.Alert) error {
88		hook := os.Getenv("SLACK_WEBHOOK")
89		if hook == "" {
90			return nil
91		}
92		return postJSON(hook, map[string]string{
93			"channel": a.Recipient,
94			"text":    a.Summary,
95		})
96	}
