118		resp, err := http.DefaultClient.Do(req)
119		if err != nil {
120			return fmt.Errorf("pagerduty: %w", err)
121		}
122		defer func() { _ = resp.Body.Close() }()
123		if resp.StatusCode >= http.StatusMultipleChoices {
124			return fmt.Errorf("pagerduty: status %d", resp.StatusCode)
125		}
126		return nil
127	}
