20	// priorityAttempts returns how many delivery attempts a priority earns.
21	func priorityAttempts(p models.Priority) int {
22		attempts := 1
23		switch p { //nolint:exhaustive // TODO
24		case models.Low:
25			attempts = 1
26		case models.Medium:
27			attempts = 3
28		}
29		return attempts
30	}
31	
32	// withRetry calls fn until it succeeds or attempts run out, backing off a
33	// second longer after each failure.
34	func withRetry(attempts int, fn func() error) error {
35		var err error
36		for attempt := 0; attempt < attempts; attempt++ {
37			if err = fn(); err == nil {
38				return nil
39			}
40			time.Sleep(time.Duration(attempt+1) * time.Second)
41		}
42		return err
43	}
44	
45	// SendWithRetry sends an alert, retrying as often as its priority allows.
46	func SendWithRetry(a models.Alert, p models.Priority) error {
47		var err error
48		for attempt := 0; attempt < priorityAttempts(p); attempt++ {
49			if err = Send(a); err == nil {
50				return nil
51			}
52			time.Sleep(retryDelay(a))
53		}
54		return err
55	}
